    {
      "policy_source_id": "q6",
      "interpretation": "The agent must not make a tool call (e.g., transfer_to_human_agents) simultaneously with sending a message to the user.",
      "modality": "FORBID"
    },
    {
      "policy_source_id": "q5",
      "interpretation": "The agent must communicate with the user in Russian and ensure valid JSON for tool calls.",
      "modality": "REQUIRE"
    }
