      "role": "agent",
      "fact": "Tool call to transfer_to_human_agents is made after exhausting all available diagnostic/resolution steps."
    },
    {
      "source_id": "q6",
      "actor": "system",
      "role": "policy",
      "fact": "Policy explicitly states transfer is only allowed if the issue cannot be resolved within the agent's scope."
    },
    {
      "source_id": "q9",
      "actor": "system",
      "role": "declaration",
      "fact": "transfer_to_human_agents tool requires a summary of the unresolved issue."
    }
